    "PBase" : {
      "type" : "number",
      "default" : 0.0000000000000000E+000,
      "description" : "Base P value for normalization. Default is zero, meaning the peak will be used.",
      "units" : "kW",
      "title" : "PBase",
      "$dssPropertyIndex" : 17,
      "$dssPropertyOrder" : 14
    },
